-- Summit Metro Parks boundary import  (ROTV issue #198)
-- Source : OpenStreetMap via Overpass API (ODbL 1.0, http://osm.org/copyright)
-- Tooling: data/boundaries/fetch_summit_metro_parks.py  (re-runnable)
-- Retrieved: 2026-05-21    Parks: 16
--
-- Schema notes (current model, NOT the legacy poi_type):
--   * poi_roles TEXT[] must contain 'boundary'
--   * boundary_type='park' -> lands in the frontend Parks panel (Map.jsx)
--     (server.js startup auto-stamps NULL boundary_type to 'municipal', so we
--      MUST set 'park' explicitly here)
--   * grounding (geoService.getContainingBoundaries) reads PostGIS boundary_geom.
BEGIN;

-- The pois id sequence can lag max(id) after past manual-id inserts; realign it.
SELECT setval(pg_get_serial_sequence('pois', 'id'),
              (SELECT GREATEST(MAX(id), 1) FROM pois));

-- One POI per park (spec 048): a park that already exists keeps its row and
-- everything attached to it; only its outline is refreshed. Never delete and
-- re-insert a park: that cascades away its news, events, photos and favorites.
CREATE TEMP TABLE park_import (
  name TEXT, poi_roles TEXT[], boundary_type TEXT, boundary_color TEXT, geometry JSONB
) ON COMMIT DROP;

INSERT INTO park_import (name, poi_roles, boundary_type, boundary_color, geometry)
