UPDATE pois p
SET geometry = i.geometry, boundary_color = i.boundary_color, updated_at = CURRENT_TIMESTAMP
FROM park_import i
WHERE p.name = i.name
  AND 'boundary' = ANY(p.poi_roles) AND p.boundary_type = 'park'
  AND p.deleted IS NOT TRUE;

INSERT INTO pois (name, poi_roles, boundary_type, boundary_color, geometry)
SELECT i.name, i.poi_roles, i.boundary_type, i.boundary_color, i.geometry
FROM park_import i
WHERE NOT EXISTS (
  SELECT 1 FROM pois p
  WHERE p.name = i.name
    AND 'boundary' = ANY(p.poi_roles) AND p.boundary_type = 'park'
    AND p.deleted IS NOT TRUE
);

-- Dissolve overlapping/multi-piece geometry. Multi-piece parks (e.g. Liberty
-- Park's 4 OSM ways) OVERLAP; ST_MakeValid would punch the overlap out as a hole
-- (even-odd rule) -- the "square cut out" of the developed core. ST_UnaryUnion
-- merges them into clean, hole-free coverage. We rewrite BOTH the JSONB (map
-- rendering) and the PostGIS column (grounding) from the same dissolved geometry.
-- Postgres evaluates both SET expressions against the pre-UPDATE row, so reading
-- and writing `geometry` in one statement is safe.
UPDATE pois
SET geometry = ST_AsGeoJSON(ST_UnaryUnion(ST_GeomFromGeoJSON(geometry::text)))::jsonb,
    boundary_geom = ST_Multi(
      ST_CollectionExtract(ST_UnaryUnion(ST_GeomFromGeoJSON(geometry::text)), 3)
    )::geometry(MultiPolygon, 4326)
WHERE boundary_type = 'park'
  AND geometry IS NOT NULL
  AND name IN ('Cascade Valley Metro Park', 'Confluence Metro Park', 'Deep Lock Quarry Metro Park', 'F.A. Seiberling Nature Realm', 'Firestone Metro Park', 'Furnace Run Metro Park', 'Goodyear Heights Metro Park', 'Gorge Metro Park', 'Hampton Hills Metro Park', 'Liberty Park', 'Munroe Falls Metro Park', 'Nimisila Reservoir Metro Park', 'O''Neil Woods Metro Park', 'Sand Run Metro Park', 'Silver Creek Metro Park', 'Springfield Bog Metro Park');

COMMIT;

-- Verification
SELECT name, ST_GeometryType(boundary_geom) AS geom_type,
       ST_NumGeometries(boundary_geom) AS parts,
       round((ST_Area(boundary_geom::geography)/4046.86)::numeric, 0) AS acres
FROM pois
WHERE boundary_type='park' AND name IN ('Cascade Valley Metro Park', 'Confluence Metro Park', 'Deep Lock Quarry Metro Park', 'F.A. Seiberling Nature Realm', 'Firestone Metro Park', 'Furnace Run Metro Park', 'Goodyear Heights Metro Park', 'Gorge Metro Park', 'Hampton Hills Metro Park', 'Liberty Park', 'Munroe Falls Metro Park', 'Nimisila Reservoir Metro Park', 'O''Neil Woods Metro Park', 'Sand Run Metro Park', 'Silver Creek Metro Park', 'Springfield Bog Metro Park')
ORDER BY acres DESC;
